FUNCTION_BLOCK FB_Semiconductor_RTP_LampEmissivity
(* ============================================================================================== *)
(* LUMINA CYBER-PHYSICAL SYSTEMS LAB - HIGH ACCURACY RTP SUB-SYSTEM FOR 300MM WAFER FABRICATION  *)
(* ARCHITECTURE: MULTI-ZONE DYNAMIC PYROMETER EMISSIVITY & HALOGEN LAMP RADIANT FLUX BALANCER   *)
(* GOVERNING SPECIFICATIONS: SEMI E10, SEMI S2/S8, IEC 61131-3 3RD ED, DIN EN 61508 (SIL 2)     *)
(* PROCESS CLASS: ADVANCED SPIKE ANNEALING / FLASH RTP (UP TO 250 deg C/s RAMP TO 1250 deg C)    *)
(* ============================================================================================== *)

VAR_INPUT
    (* Master Execution and Safety Interlocks *)
    bEnable                 : BOOL;     (* Master controller software arming signal [TRUE = Armed] *)
    bEmergencyStop          : BOOL;     (* Hardware E-Stop contact chain / SIS relay status [TRUE = Healthy] *)
    bRecipeStart            : BOOL;     (* Automated recipe initiation strobe from host EAP [Pulsed] *)
    bRecipeAbort            : BOOL;     (* Immediate abort & chamber inert purge command [Pulsed] *)

    (* Dynamic Process Recipe Targets *)
    rTargetTemp             : REAL;     (* Final soak target temperature [deg C] (Valid: 200.0 to 1250.0) *)
    rTargetRampRate         : REAL;     (* Requested wafer heating trajectory ramp rate [deg C/s] (Valid: 1.0 to 250.0) *)
    rSoakTimeSec            : REAL;     (* Steady-state dwell duration at peak temperature [s] (0.1 to 120.0) *)

    (* Process Environment State Sensors *)
    rChamberPressure        : REAL;     (* Chamber capacitance manometer reading [Torr] (0.001 to 760.0) *)
    rProcessGasFlow_N2      : REAL;     (* Inert purge gas mass flow controller feedback [sccm] (0.0 to 50000.0) *)
    rProcessGasFlow_O2      : REAL;     (* Reactive oxidation gas mass flow controller [sccm] (0.0 to 5000.0) *)
    rWaferRotationRPM       : REAL;     (* Non-contact magnetic levitation chuck rotary speed [RPM] (Target: 90.0) *)

    (* Electrical Actuator Feedback *)
    rLampPowerFeedbackTotal : REAL;     (* Multi-tap SCR primary phase angle power summation [kW] (0.0 to 140.0) *)

    (* Optical Metrology Sensors: 2oo3 TMR Zone 1 Center Pyrometers & Multi-Wavelength Periphery *)
    rPyrometerRawTemp_Z1_A  : REAL;     (* Zone 1 Center high-speed pyrometer optical head A [deg C] *)
    rPyrometerRawTemp_Z1_B  : REAL;     (* Zone 1 Center high-speed pyrometer optical head B [deg C] *)
    rPyrometerRawTemp_Z1_C  : REAL;     (* Zone 1 Center high-speed pyrometer optical head C [deg C] *)
    rPyrometerRawTemp_Z2    : REAL;     (* Zone 2 Mid-radius pyrometer optical sensor [deg C] *)
    rPyrometerRawTemp_Z3    : REAL;     (* Zone 3 Edge boundary pyrometer optical sensor [deg C] *)
    rInSituReflectance      : REAL;     (* Co-axial laser reflectometer 950nm reflectance ratio [0.000 to 1.000] *)
    rBacksideEmissivityInit : REAL;     (* Pre-calibrated substrate backside baseline emissivity [0.05 to 0.98] *)

    (* Timing Base *)
    tCycleTime              : TIME := T#10MS; (* Cyclic execution task interval (10 ms scan) *)
END_VAR

VAR_OUTPUT
    (* Equipment & Health Status *)
    bSystemReady            : BOOL;     (* RTP Chamber interlocks satisfied, pyrometers online, ready for recipe *)
    bThermalRunawayAlarm    : BOOL;     (* Instantaneous over-temperature or excessive dT/dt rate violation tripped *)
    bTMRDiscrepancyAlarm    : BOOL;     (* Sensor divergence detected in 2oo3 voting kernel (tolerance exceeded) *)
    wStatusWord             : WORD;     (* SEMI E10 equipment state & subsystem status word bitfield *)
    wAlarmCode              : WORD;     (* Hex fault diagnostic word: bit 0: E-Stop, bit 1: Runaway, bit 2: TMR, etc. *)

    (* Multi-Zone Radiant Flux Demands (SCR Actuator Interface) *)
    rZone1_LampPowerCmd     : REAL;     (* Zone 1 (Wafer Center Core) Halogen radiant bank demand [kW] *)
    rZone2_LampPowerCmd     : REAL;     (* Zone 2 (Inner Ring Array) Halogen radiant bank demand [kW] *)
    rZone3_LampPowerCmd     : REAL;     (* Zone 3 (Outer Ring Array) Halogen radiant bank demand [kW] *)
    rZone4_LampPowerCmd     : REAL;     (* Zone 4 (Wafer Bevel / Edge Guard Ring) Halogen radiant demand [kW] *)

    (* Real-Time Compensated Process Variables *)
    rWaferTempFiltered      : REAL;     (* 2oo3 Voted & emissivity-corrected true substrate temperature [deg C] *)
    rCalculatedEmissivity   : REAL;     (* Real-time dynamic emissivity coefficient epsilon(T, lambda) [dimensionless] *)
    rRadialTempUniformity   : REAL;     (* Measured cross-wafer thermal non-uniformity peak delta (Max - Min) [deg C] *)
END_VAR

VAR
    (* Sequencer State Enumeration *)
    iState                  : INT := 0; 
    (* 0: IDLE / SAFE_SHUTDOWN                                                                       *)
    (* 10: CHAMBER_PUMPDOWN_AND_GAS_STABILIZE                                                        *)
    (* 20: WAFER_LEVITATION_AND_OPTICAL_ALIGNMENT                                                    *)
    (* 30: LOW_TEMP_PREHEAT_AND_EMISSIVITY_SEEDING                                                   *)
    (* 40: DYNAMIC_HIGH_SPEED_RAMP                                                                   *)
    (* 50: HIGH_TEMP_ISOTHERMAL_SOAK                                                                 *)
    (* 60: CONTROLLED_RADIATIVE_RAMP_DOWN                                                            *)
    (* 70: FORCED_CONVECTIVE_N2_PURGE_COOL                                                           *)
    (* 99: CRITICAL_SAFETY_FAULT_HOLD                                                                *)

    (* Trajectory Profiler Variables *)
    rActiveTempSetpoint     : REAL := 25.0;     (* Current dynamic trajectory setpoint [deg C] *)
    rRampStepPerScan        : REAL := 0.0;      (* Incremental setpoint advancement per 10ms scan [deg C] *)
    rCycleTimeSec           : REAL := 0.010;    (* Execution period converted to seconds [s] *)

    (* 2oo3 TMR (Triple Modular Redundancy) Pyrometer Engine *)
    rVotedTemp_Z1           : REAL := 25.0;     (* Arbitrated center pyrometer temperature [deg C] *)
    bSensorA_Healthy        : BOOL := TRUE;
    bSensorB_Healthy        : BOOL := TRUE;
    bSensorC_Healthy        : BOOL := TRUE;
    rDelta_AB               : REAL := 0.0;      (* Absolute variance between Sensor A and B [deg C] *)
    rDelta_BC               : REAL := 0.0;      (* Absolute variance between Sensor B and C [deg C] *)
    rDelta_CA               : REAL := 0.0;      (* Absolute variance between Sensor C and A [deg C] *)
    iHealthySensorCount     : INT := 3;         (* Number of active concurring pyrometer heads [0..3] *)
    rTMR_ToleranceBand      : REAL := 4.5;      (* Maximum allowable inter-sensor disagreement [deg C] *)

    (* Dynamic Emissivity Calibration Model (Kirchhoff Law & Planck Radiation Inversion) *)
    rTrueTemp_Z1            : REAL := 25.0;     (* Emissivity-compensated Zone 1 temperature [deg C] *)
    rTrueTemp_Z2            : REAL := 25.0;     (* Emissivity-compensated Zone 2 temperature [deg C] *)
    rTrueTemp_Z3            : REAL := 25.0;     (* Emissivity-compensated Zone 3 temperature [deg C] *)
    rEffectiveWavelength    : REAL := 0.950E-6; (* Pyrometer center spectral band [m] (950 nm) *)
    rPlanckC2               : REAL := 0.014388; (* Second radiation constant hc/k_B [m*K] *)
    rInvTempKelvin          : REAL;
    rApparentKelvin         : REAL;

    (* Model Predictive Radiant Flux Balancing: Inverted 4x4 Chamber Thermal View Factor Matrix      *)
    (* Resolves dynamic cross-radiation from 4 lamp rings onto 3 wafer concentric zones + guard ring *)
    (* Units of A_inv elements: [kW applied / kW absorbed]                                            *)
    rA_inv_11               : REAL :=  1.2850;  rA_inv_12 : REAL := -0.1950;  rA_inv_13 : REAL := -0.0450;  rA_inv_14 : REAL := -0.0120;
    rA_inv_21               : REAL := -0.1620;  rA_inv_22 : REAL :=  1.3400;  rA_inv_23 : REAL := -0.2180;  rA_inv_24 : REAL := -0.0380;
    rA_inv_31               : REAL := -0.0380;  rA_inv_32 : REAL := -0.2240;  rA_inv_33 : REAL :=  1.4250;  rA_inv_34 : REAL := -0.2750;
    rA_inv_41               : REAL := -0.0090;  rA_inv_42 : REAL := -0.0420;  rA_inv_43 : REAL := -0.2820;  rA_inv_44 : REAL :=  1.6200;

    (* Zone Flux Virtual Demands [kW] *)
    rFluxDemand_Z1          : REAL := 0.0;
    rFluxDemand_Z2          : REAL := 0.0;
    rFluxDemand_Z3          : REAL := 0.0;
    rFluxDemand_Z4          : REAL := 0.0;

    (* Peripheral Radiative Edge Loss Guard Ring Compensation *)
    rStefanBoltzmann        : REAL := 5.67037E-8; (* Stefan-Boltzmann constant [W/(m^2*K^4)] *)
    rWaferBevelArea         : REAL := 0.000725;   (* 300mm wafer circumferential bevel area [m^2] *)
    rChamberWallTempKelvin  : REAL := 303.15;     (* Water-cooled chamber cold-wall temperature [K] (30 deg C) *)
    rEdgeLossFlux           : REAL := 0.0;        (* Edge radiative heat dump to water-cooled cold-wall [kW] *)

    (* Multi-Zone PID Flux Compensator Accumulators *)
    rErr_Z1                 : REAL := 0.0;
    rErr_Z2                 : REAL := 0.0;
    rErr_Z3                 : REAL := 0.0;
    rInteg_Z1               : REAL := 0.0;
    rInteg_Z2               : REAL := 0.0;
    rInteg_Z3               : REAL := 0.0;
    rDeriv_Z1               : REAL := 0.0;
    rDeriv_Z2               : REAL := 0.0;
    rDeriv_Z3               : REAL := 0.0;
    rPrevErr_Z1             : REAL := 0.0;
    rPrevErr_Z2             : REAL := 0.0;
    rPrevErr_Z3             : REAL := 0.0;

    (* High-Performance PID Gains *)
    rGainKp                 : REAL := 0.0620;   (* Proportional gain [kW / deg C] *)
    rGainKi                 : REAL := 0.0095;   (* Integral gain [kW / (deg C * s)] *)
    rGainKd                 : REAL := 0.0035;   (* Derivative gain [kW * s / deg C] *)

    (* Supervisory Monitoring & Thermal Velocity Observers *)
    rPrevMeasuredTemp       : REAL := 25.0;
    rMeasuredRampRate       : REAL := 0.0;      (* Measured instantaneous heating rate [deg C/s] *)
    rMinTempObserved        : REAL := 0.0;
    rMaxTempObserved        : REAL := 0.0;

    (* Sequence & Diagnostic Timers *)
    tPurgeTimer             : TON;
    tSoakTimer              : TON;
    tCoolTimer              : TON;
    tFaultHoldTimer         : TON;
    tPreheatTimer           : TON;

    (* Hard Safety Threshold Constants *)
    cMAX_ALLOWABLE_TEMP     : REAL := 1280.0;   (* Absolute safety cutoff limit for 300mm Si wafer [deg C] *)
    cMAX_ALLOWABLE_RAMP     : REAL := 280.0;    (* Max allowable dT/dt thermal stress boundary [deg C/s] *)
    cMIN_CHAMBER_PRESSURE   : REAL := 0.010;    (* Minimum base vacuum threshold [Torr] *)
    cMAX_CHAMBER_PRESSURE   : REAL := 780.0;    (* Maximum overpressure relief threshold [Torr] *)
    cMIN_WAFER_ROTATION_RPM : REAL := 75.0;     (* Minimum chuck rotation to prevent azimuth slip dislocations [RPM] *)
    cMAX_ZONE_POWER_KW      : REAL := 35.0;     (* Individual SCR lamp zone rating ceiling [kW] *)
END_VAR

(* ============================================================================================== *)
(*                                       MAIN ALGORITHMIC LOGIC                                   *)
(* ============================================================================================== *)

(* ---------------------------------------------------------------------------------------------- *)
(* LAYER 0: HARDWARE SAFETY INTERLOCK & EMERGENCY SHUTDOWN EVALUATION                             *)
(* ---------------------------------------------------------------------------------------------- *)
IF NOT bEmergencyStop THEN
    (* Immediate de-energization of all SCR halogen firing boards *)
    rZone1_LampPowerCmd  := 0.0;
    rZone2_LampPowerCmd  := 0.0;
    rZone3_LampPowerCmd  := 0.0;
    rZone4_LampPowerCmd  := 0.0;
    bSystemReady         := FALSE;
    bThermalRunawayAlarm := FALSE;
    wAlarmCode           := 16#0001; (* Bit 0: Emergency Stop Loop Tripped *)
    wStatusWord          := 16#8000; (* SEMI E10: Non-Scheduled Down / Emergency Stop *)
    iState               := 99;      (* Shift into Safe Emergency Hold *)
    RETURN;
END_IF;

IF NOT bEnable THEN
    rZone1_LampPowerCmd  := 0.0;
    rZone2_LampPowerCmd  := 0.0;
    rZone3_LampPowerCmd  := 0.0;
    rZone4_LampPowerCmd  := 0.0;
    bSystemReady         := FALSE;
    wStatusWord          := 16#0001; (* SEMI E10: Standby / Disabled *)
    iState               := 0;
    RETURN;
END_IF;

(* ---------------------------------------------------------------------------------------------- *)
(* LAYER 1: 2oo3 TRIPLE MODULAR REDUNDANCY (TMR) VOTING & SENSOR VALIDATION FOR ZONE 1 PYROMETER  *)
(* ---------------------------------------------------------------------------------------------- *)
rDelta_AB := ABS(rPyrometerRawTemp_Z1_A - rPyrometerRawTemp_Z1_B);
rDelta_BC := ABS(rPyrometerRawTemp_Z1_B - rPyrometerRawTemp_Z1_C);
rDelta_CA := ABS(rPyrometerRawTemp_Z1_C - rPyrometerRawTemp_Z1_A);

bSensorA_Healthy := (rDelta_AB <= rTMR_ToleranceBand) OR (rDelta_CA <= rTMR_ToleranceBand);
bSensorB_Healthy := (rDelta_AB <= rTMR_ToleranceBand) OR (rDelta_BC <= rTMR_ToleranceBand);
bSensorC_Healthy := (rDelta_BC <= rTMR_ToleranceBand) OR (rDelta_CA <= rTMR_ToleranceBand);

iHealthySensorCount := 0;
IF bSensorA_Healthy THEN iHealthySensorCount := iHealthySensorCount + 1; END_IF;
IF bSensorB_Healthy THEN iHealthySensorCount := iHealthySensorCount + 1; END_IF;
IF bSensorC_Healthy THEN iHealthySensorCount := iHealthySensorCount + 1; END_IF;

IF (iHealthySensorCount = 3) THEN
    (* Full 3-channel consensus: select median sensor to eliminate optical spike noise *)
    IF ((rPyrometerRawTemp_Z1_A >= rPyrometerRawTemp_Z1_B) AND (rPyrometerRawTemp_Z1_A <= rPyrometerRawTemp_Z1_C)) OR
       ((rPyrometerRawTemp_Z1_A <= rPyrometerRawTemp_Z1_B) AND (rPyrometerRawTemp_Z1_A >= rPyrometerRawTemp_Z1_C)) THEN
        rVotedTemp_Z1 := rPyrometerRawTemp_Z1_A;
    ELSIF ((rPyrometerRawTemp_Z1_B >= rPyrometerRawTemp_Z1_A) AND (rPyrometerRawTemp_Z1_B <= rPyrometerRawTemp_Z1_C)) OR
          ((rPyrometerRawTemp_Z1_B <= rPyrometerRawTemp_Z1_A) AND (rPyrometerRawTemp_Z1_B >= rPyrometerRawTemp_Z1_C)) THEN
        rVotedTemp_Z1 := rPyrometerRawTemp_Z1_B;
    ELSE
        rVotedTemp_Z1 := rPyrometerRawTemp_Z1_C;
    END_IF;
    bTMRDiscrepancyAlarm := FALSE;
ELSIF (iHealthySensorCount = 2) THEN
    (* Degraded 1oo2 mode: average the two conforming optical channels, isolate drifted head *)
    IF bSensorA_Healthy AND bSensorB_Healthy THEN
        rVotedTemp_Z1 := (rPyrometerRawTemp_Z1_A + rPyrometerRawTemp_Z1_B) * 0.5;
    ELSIF bSensorB_Healthy AND bSensorC_Healthy THEN
        rVotedTemp_Z1 := (rPyrometerRawTemp_Z1_B + rPyrometerRawTemp_Z1_C) * 0.5;
    ELSE
        rVotedTemp_Z1 := (rPyrometerRawTemp_Z1_C + rPyrometerRawTemp_Z1_A) * 0.5;
    END_IF;
    bTMRDiscrepancyAlarm := TRUE;
    wAlarmCode := wAlarmCode OR 16#0004; (* Bit 2: Pyrometer Head Degradation Warning *)
ELSE
    (* Total TMR divergence failure: fallback to spatial estimation using Zone 2 pyrometer *)
    rVotedTemp_Z1 := rPyrometerRawTemp_Z2 + 2.5; (* Spatial model offset approximation *)
    bTMRDiscrepancyAlarm := TRUE;
    wAlarmCode := wAlarmCode OR 16#0008; (* Bit 3: Critical Pyrometer TMR Loss *)
END_IF;

(* ---------------------------------------------------------------------------------------------- *)
(* LAYER 2: DYNAMIC EMISSIVITY CORRECTION & TRUE TEMPERATURE OBSERVER VIA PLANCK INVERSION        *)
(* ---------------------------------------------------------------------------------------------- *)
(* Kirchhoff Law of Thermal Radiation: Emissivity epsilon = 1.0 - Reflectance R                   *)
IF (rInSituReflectance >= 0.010) AND (rInSituReflectance <= 0.950) THEN
    rCalculatedEmissivity := 1.000 - rInSituReflectance;
ELSE
    rCalculatedEmissivity := rBacksideEmissivityInit;
END_IF;

(* Bound calculated emissivity to physical dielectric/doped silicon limits *)
IF rCalculatedEmissivity < 0.050 THEN
    rCalculatedEmissivity := 0.050;
ELSIF rCalculatedEmissivity > 0.980 THEN
    rCalculatedEmissivity := 0.980;
END_IF;

(* Radiance Temperature to True Wafer Temperature via Wien-Planck Displacement Formulation:      *)
(* 1 / T_true = 1 / T_apparent + (lambda / c_2) * ln(epsilon)                                     *)
rApparentKelvin := rVotedTemp_Z1 + 273.15;
IF rApparentKelvin > 150.0 THEN
    rInvTempKelvin := (1.0 / rApparentKelvin) + ((rEffectiveWavelength / rPlanckC2) * LN(rCalculatedEmissivity));
    IF rInvTempKelvin > 0.0004 THEN
        rTrueTemp_Z1 := (1.0 / rInvTempKelvin) - 273.15;
    ELSE
        rTrueTemp_Z1 := rVotedTemp_Z1;
    END_IF;
ELSE
    rTrueTemp_Z1 := rVotedTemp_Z1;
END_IF;

(* Secondary Zones Emissivity Correction *)
rApparentKelvin := rPyrometerRawTemp_Z2 + 273.15;
IF rApparentKelvin > 150.0 THEN
    rInvTempKelvin := (1.0 / rApparentKelvin) + ((rEffectiveWavelength / rPlanckC2) * LN(rCalculatedEmissivity));
    rTrueTemp_Z2 := (1.0 / rInvTempKelvin) - 273.15;
ELSE
    rTrueTemp_Z2 := rPyrometerRawTemp_Z2;
END_IF;

rApparentKelvin := rPyrometerRawTemp_Z3 + 273.15;
IF rApparentKelvin > 150.0 THEN
    rInvTempKelvin := (1.0 / rApparentKelvin) + ((rEffectiveWavelength / rPlanckC2) * LN(rCalculatedEmissivity));
    rTrueTemp_Z3 := (1.0 / rInvTempKelvin) - 273.15;
ELSE
    rTrueTemp_Z3 := rPyrometerRawTemp_Z3;
END_IF;

(* Composite Filtered Wafer Temperature for Primary Control Loop *)
rWaferTempFiltered := rTrueTemp_Z1;

(* Calculate Cross-Wafer Radial Uniformity Metric *)
rMaxTempObserved := rTrueTemp_Z1;
IF rTrueTemp_Z2 > rMaxTempObserved THEN rMaxTempObserved := rTrueTemp_Z2; END_IF;
IF rTrueTemp_Z3 > rMaxTempObserved THEN rMaxTempObserved := rTrueTemp_Z3; END_IF;

rMinTempObserved := rTrueTemp_Z1;
IF rTrueTemp_Z2 < rMinTempObserved THEN rMinTempObserved := rTrueTemp_Z2; END_IF;
IF rTrueTemp_Z3 < rMinTempObserved THEN rMinTempObserved := rTrueTemp_Z3; END_IF;

rRadialTempUniformity := rMaxTempObserved - rMinTempObserved;

(* ---------------------------------------------------------------------------------------------- *)
(* LAYER 3: THERMAL RUNAWAY & ENVELOPE DYNAMICS SAFETY SUPERVISION                               *)
(* ---------------------------------------------------------------------------------------------- *)
rMeasuredRampRate := (rWaferTempFiltered - rPrevMeasuredTemp) / rCycleTimeSec;
rPrevMeasuredTemp := rWaferTempFiltered;

IF (rWaferTempFiltered >= cMAX_ALLOWABLE_TEMP) OR (ABS(rMeasuredRampRate) >= cMAX_ALLOWABLE_RAMP) THEN
    bThermalRunawayAlarm := TRUE;
    wAlarmCode := wAlarmCode OR 16#0002; (* Bit 1: Thermal Runaway Excursion Trip *)
    iState := 99; (* Instantaneous transfer to Emergency Fault Hold *)
END_IF;

IF (rChamberPressure < cMIN_CHAMBER_PRESSURE) OR (rChamberPressure > cMAX_CHAMBER_PRESSURE) THEN
    wAlarmCode := wAlarmCode OR 16#0010; (* Bit 4: Chamber Pressure Boundary Violation *)
END_IF;

IF (rWaferRotationRPM < cMIN_WAFER_ROTATION_RPM) AND (iState >= 30) THEN
    wAlarmCode := wAlarmCode OR 16#0020; (* Bit 5: Chuck Levitation / Speed Loss *)
END_IF;

(* ---------------------------------------------------------------------------------------------- *)
(* LAYER 4: MULTI-STAGE REPRODUCTIVE RTP THERMAL STATE MACHINE                                    *)
(* ---------------------------------------------------------------------------------------------- *)
CASE iState OF
    0: (* STATE 0: IDLE / STANDBY INITIALIZATION *)
        bSystemReady            := (rChamberPressure <= 5.0) AND (wAlarmCode = 0) AND (rProcessGasFlow_N2 >= 5000.0);
        rZone1_LampPowerCmd     := 0.0;
        rZone2_LampPowerCmd     := 0.0;
        rZone3_LampPowerCmd     := 0.0;
        rZone4_LampPowerCmd     := 0.0;
        rActiveTempSetpoint     := rWaferTempFiltered;
        rInteg_Z1               := 0.0;
        rInteg_Z2               := 0.0;
        rInteg_Z3               := 0.0;
        wStatusWord             := 16#0002; (* SEMI E10: Idle / Ready *)

        tPurgeTimer(IN := FALSE, PT := T#5S);
        tSoakTimer(IN := FALSE, PT := REAL_TO_TIME(rSoakTimeSec * 1000.0));
        tCoolTimer(IN := FALSE, PT := T#15S);

        IF bRecipeStart AND bSystemReady THEN
            iState := 10;
        END_IF;

    10: (* STATE 10: CHAMBER PUMPDOWN & ATMOSPHERE GAS STABILIZATION *)
        wStatusWord := 16#0010; (* Process Active: Gas Stabilization *)
        tPurgeTimer(IN := TRUE, PT := T#5S);

        IF (rProcessGasFlow_N2 >= 15000.0) AND (rChamberPressure <= 2.0) AND tPurgeTimer.Q THEN
            tPurgeTimer(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* STATE 20: WAFER MAGNETIC LEVITATION & AZIMUTH ROTATION SPIN-UP *)
        wStatusWord := 16#0020; (* Process Active: Rotation Acceleration *)

        IF (rWaferRotationRPM >= 88.0) AND (rWaferRotationRPM <= 92.0) THEN
            iState := 30;
        END_IF;

    30: (* STATE 30: LOW-TEMPERATURE PREHEAT & DYNAMIC EMISSIVITY SEEDING *)
        wStatusWord := 16#0030; (* Process Active: Preheat Baseline *)
        rActiveTempSetpoint := 400.0; (* 400 deg C preheat plateau *)
        tPreheatTimer(IN := TRUE, PT := T#3S);

        IF (ABS(rWaferTempFiltered - 400.0) <= 5.0) AND tPreheatTimer.Q THEN
            tPreheatTimer(IN := FALSE);
            iState := 40;
        END_IF;

    40: (* STATE 40: DYNAMIC HIGH-SPEED CLOSED-LOOP HEATING RAMP *)
        wStatusWord := 16#0040; (* Process Active: High-Speed Spike Ramp *)
        rRampStepPerScan := (rTargetRampRate * rCycleTimeSec);

        IF rActiveTempSetpoint < rTargetTemp THEN
            rActiveTempSetpoint := rActiveTempSetpoint + rRampStepPerScan;
            IF rActiveTempSetpoint > rTargetTemp THEN
                rActiveTempSetpoint := rTargetTemp;
            END_IF;
        END_IF;

        IF (rWaferTempFiltered >= (rTargetTemp - 2.0)) THEN
            rActiveTempSetpoint := rTargetTemp;
            iState := 50;
        END_IF;

    50: (* STATE 50: HIGH-TEMPERATURE ISOTHERMAL SOAK / ACTIVATION DWELL *)
        wStatusWord := 16#0050; (* Process Active: Soak Phase *)
        rActiveTempSetpoint := rTargetTemp;
        tSoakTimer(IN := TRUE, PT := REAL_TO_TIME(rSoakTimeSec * 1000.0));

        IF tSoakTimer.Q THEN
            tSoakTimer(IN := FALSE);
            iState := 60;
        END_IF;

    60: (* STATE 60: CONTROLLED RADIATIVE RAMP-DOWN *)
        wStatusWord := 16#0060; (* Process Active: Radiative Ramp-Down *)
        rRampStepPerScan := (80.0 * rCycleTimeSec); (* Controlled -80 deg C/s cool down *)

        IF rActiveTempSetpoint > 450.0 THEN
            rActiveTempSetpoint := rActiveTempSetpoint - rRampStepPerScan;
        ELSE
            iState := 70;
        END_IF;

    70: (* STATE 70: HIGH CONVECTIVE N2 PURGE COOLING BELOW SLIP RISK *)
        wStatusWord := 16#0070; (* Process Active: Forced N2 Quench *)
        rActiveTempSetpoint := 25.0;
        rZone1_LampPowerCmd := 0.0;
        rZone2_LampPowerCmd := 0.0;
        rZone3_LampPowerCmd := 0.0;
        rZone4_LampPowerCmd := 0.0;
        tCoolTimer(IN := TRUE, PT := T#20S);

        IF (rWaferTempFiltered <= 80.0) OR tCoolTimer.Q THEN
            tCoolTimer(IN := FALSE);
            iState := 0; (* Cycle successfully completed, return to IDLE *)
        END_IF;

    99: (* STATE 99: CRITICAL SAFETY FAULT HOLD *)
        wStatusWord := 16#0099; (* SEMI E10: Emergency Fault Lockout *)
        rZone1_LampPowerCmd := 0.0;
        rZone2_LampPowerCmd := 0.0;
        rZone3_LampPowerCmd := 0.0;
        rZone4_LampPowerCmd := 0.0;
        rActiveTempSetpoint := 25.0;

        (* Latch until enable reset and E-Stop healthy *)
        IF NOT bEnable AND bEmergencyStop THEN
            wAlarmCode := 0;
            bThermalRunawayAlarm := FALSE;
            bTMRDiscrepancyAlarm := FALSE;
            iState := 0;
        END_IF;

END_CASE;

(* Intercept recipe abort command in any active state *)
IF bRecipeAbort AND (iState > 0) AND (iState < 99) THEN
    iState := 70; (* Divert to emergency convective cool-down sequence *)
END_IF;

(* ---------------------------------------------------------------------------------------------- *)
(* LAYER 5: ZONE FLUX CONTROLLER & MODEL PREDICTIVE RADIANT BALANCE (MPC DECOUPLING)              *)
(* ---------------------------------------------------------------------------------------------- *)
IF (iState >= 30) AND (iState <= 60) THEN
    (* Multi-Zone Tracking Error Calculations *)
